  1339  jv jv_string_repeat(jv j, int n) {
  1340    assert(JVP_HAS_KIND(j, JV_KIND_STRING));
  1341    if (n < 0) {
  1342      jv_free(j);
  1343      return jv_null();
  1344    }
  1345    int len = jv_string_length_bytes(jv_copy(j));
  1346    int64_t res_len = (int64_t)len * n;
  1347    if (res_len >= INT_MAX) {
  1348      jv_free(j);
  1349      return jv_invalid_with_msg(jv_string("Repeat string result too long"));
  1350    }
  1351    if (res_len == 0) {
  1352      jv_free(j);
  1353      return jv_string("");
  1354    }
  1355    jv res = jv_string_empty(res_len);
  1356    res = jvp_string_append(res, jv_string_value(j), len);
  1357    for (int curr = len, grow; curr < res_len; curr += grow) {
  1358      grow = MIN(res_len - curr, curr);
  1359      res = jvp_string_append(res, jv_string_value(res), grow);
  1360    }
  1361    jv_free(j);
  1362    return res;
  1363  }
